            unique_emails.insert(email);
        }
        return unique_emails.size();
    }
};

0205-isomorphic-strings:
/*Given two strings s and t, determine if they are isomorphic.

Two strings s and t are isomorphic if the characters in s can be replaced to get t.

All occurrences of a character must be replaced with another character while preserving the order of characters. No two characters may map to the same character, but a character may map to itself.

 */
class Solution {
public:
    bool isIsomorphic(string s, string t) {
       unordered_map<char,vector<int>>m1;
         unordered_map<char,vector<int>>m2;
        for(int i=0;i<s.length();i++){
            m1[s[i]].push_back(i);
             m2[t[i]].push_back(i);

            if(m1[s[i]]!=m2[t[i]])
                return false;
        }
        return true;

    }
};

0605-can-place-flowers:
class Solution {
public:
    bool canPlaceFlowers(vector<int>& flowerbed, int n) {
        // pre-check, if n is 0 ... return true
        if(n == 0){
            return true;
        }

        // add a zero to the front and end of FB
        flowerbed.insert (flowerbed.begin(),0);
        flowerbed.push_back(0);

        // iterate through vector (1, vector -1) (for)
        //  if prev, curr, and next are 0
        //      plant flower (1)
        //      decrement n
        for(int i = 1; i < flowerbed.size() - 1; i++){
            if (flowerbed[i - 1] == 0 && flowerbed[i] == 0 && flowerbed[i+1] == 0){
                flowerbed[i] = 1;
                n--;
            }
            if (n == 0){
                return true;
            }

        }

        // return false as else
        return false;

    }
};

