    Keep the track of the ratios in a hash map

    Time complexity : O(n)
    Space complexity: O(n)

    n is number of rectangles
*/

class Solution {
public:
    long long interchangeableRectangles(vector<vector<int>>& rectangles) {

        map<long double,int> hash;
        long double ratio;

        long long answer=0;

        for(int i=0;i<rectangles.size();i++){
            ratio = (long double)(rectangles[i][0])/
                    (long double)(rectangles[i][1]);

            if(hash.find(ratio)!=hash.end()){
                hash[ratio]++;
            }
            else{
                hash[ratio] = 1;
            }
        }

        for(auto it:hash){
            answer+= (long long)(it.second)*(long long)(it.second-1)/2;
        }

        return answer;
    }
};

2002-maximum-product-of-the-length-of-tw:
 /*
    Approach: 
    Need to create all the disjoin subsequence and check if they are palindrome.
    keep track of maximum product 

    Time complexity : O(N*N^3)
    Space complexity: O(N)

    N is length of the string
*/


class Solution {
public:

    int answer = INT_MIN;

    // function to check if the string is a palindrome
    bool isPalindrome(string &s){
        int start = 0;
        int end = s.length() - 1;

        while(start<end){
            if(s[start]!=s[end]){
                return false;
            }
            start++;
            end--;
        }

        return true;
    }

    // function to generate all the disjoint subsequence
    void generateAll(int idx, string &s1, string &s2, string& s){

        if(idx >= s.length())
        {
            if(isPalindrome(s1)&&isPalindrome(s2)){
                int l = s1.length()*s2.length();
                answer = max(answer,l);
            }
            return;
        }

        char c = s[idx];

        /* 
        we have three options
        1. Add the char to the first string
        2. Add the char to the second string
        3. Add the char to none of the string
        */

        // add the character in the first string
        s1.push_back(c);
        generateAll(idx+1,s1,s2,s);
        s1.pop_back();

        // add the character in the second string
        s2.push_back(c);
        generateAll(idx+1,s1,s2,s);
        s2.pop_back();

        // add character in no string
        generateAll(idx+1,s1,s2,s);
    }

    int maxProduct(string s) {

        string s1 = "";
        string s2 = "";
        int idx = 0;

        generateAll(idx,s1,s2,s);

        return answer;
    }


};

2017-grid-game:
/* 
Approch:
    2nd robot can collect either all the bottom points
    before the break point (when 1st robot goes to bottom)
    or collect all the top points after that break point.
Time Complexity: O(N)
Space Complexity: O(1)
*/

class Solution {
public:
    long long gridGame(vector<vector<int>>& grid) {

        // prefix sum
        long long top = grid[0][0],bottom = 0, answer = LONG_MAX;
        for(int i =1;i<grid[0].size();i++){
            top += grid[0][i];
        }

        for(int i =0;i<grid[0].size();i++){
            // All the top points 2nd robot can collect
            top -= grid[0][i];

            // min because first robot wants to  minimize 
            answer = min(answer,max(top,bottom));

            // All the bootom points the robot could collect
            bottom += grid[1][i];
        }

        return answer;
    }
};

