                continue;

            for(char b = a+1; b <= 'z'; b++){

                if(dict.find(b) == dict.end())
                    continue;

                int aKeys = dict[a].size();
                int bKeys = dict[b].size();

                for(const string& suffix : dict[a]){
                    if(dict[b].find(suffix) != dict[b].end()){
                        aKeys--;
                        bKeys--;
                    }
                }

                count += 2 * (aKeys*bKeys);
            }
        }

        return count;
    }
};

0125-valid-palindrome:
/*
    Given a string s, return true if it's a palindrome
    Ex. s = "A man, a plan, a canal: Panama" -> true

    2 pointers, outside in, skip non-letters & compare

    Time: O(n)
    Space: O(1)
*/

class Solution {
public:
    bool isPalindrome(string s) {
        int i = 0;
        int j = s.size() - 1;

        while (i < j) {
            while (!isalnum(s[i]) && i < j) {
                i++;
            }
            while (!isalnum(s[j]) && i < j) {
                j--;
            }
            if (tolower(s[i]) != tolower(s[j])) {
                return false;
            }
            i++;
            j--;
        }

        return true;
    }
};

