0701-insert-into-a-binary-search-tree:
/*
    You are given the root node of a binary search tree (BST) and a value to insert into the tree. 
    Return the root node of the BST after the insertion. It is guaranteed that the new value does not exist in the original BST.

    Notice that there may exist multiple valid ways for the insertion, as long as the tree remains a BST after insertion. 
    You can return any of them.

    Ex. Input: root = [4,2,7,1,3], val = 5
        Output: [4,2,7,1,3,5]

    Time  : O(N)
    Space : O(N)
*/

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    TreeNode * create(int val) {
        TreeNode *n = new TreeNode;
        n -> val = val;
        n -> left = n -> right = NULL;
        return n;
    }

    TreeNode* insertIntoBST(TreeNode* root, int val) {
        if(root == NULL) 
            return create(val);

        else if(val > root -> val)
            root -> right = insertIntoBST(root -> right, val); 
        else if(val < root -> val)
            root -> left = insertIntoBST(root -> left, val);
        return root;
    }
};

0450-delete-node-in-a-bst:
/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */

// Time: O(h)
// Space: O(1)
class Solution {
public:
    TreeNode* deleteNode(TreeNode* root, int key) {
        if(root == nullptr) return root;

        if(root->val > key) {
            root->left = deleteNode(root->left, key);
        }
        else if(root->val < key) {
            root->right = deleteNode(root->right, key);
        }

        // perform deletion if root->val == key
        else {
            if(!root->left) return root->right;
            if(!root->right) return root->left;

            // both left and right subtrees are not null
            // traverse the right subtree to find the minimum/leftmost value
            // (or) travel the left subtree to find the maximum/rightmost value
            TreeNode* temp = root->right;
            while(temp->left) {
                temp = temp->left;
            }
            root->val = temp->val;

            root->right = deleteNode(root->right, temp->val);
        }

        return root;
    }
};

0102-binary-tree-level-order-traversal:
/*
    Given root of binary tree, return level order traversal of its nodes (left to right)
    Ex. root = [3,9,20,null,null,15,7] -> [[3],[9,20],[15,7]]

    Standard BFS traversal, at each level, push left & right nodes if they exist to queue

    Time: O(n)
    Space: O(n)
*/

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    vector<vector<int>> levelOrder(TreeNode* root) {
        vector<vector<int>> result;

        if (root == NULL) {
            return result;
        }

        queue<TreeNode*> q;
        q.push(root);

        while (!q.empty()) {
            int count = q.size();
            vector<int> curr;

            for (int i = 0; i < count; i++) {
                TreeNode* node = q.front();
                q.pop();

                curr.push_back(node->val);

                if (node->left != NULL) {
                    q.push(node->left);
                }
                if (node->right != NULL) {
                    q.push(node->right);
                }
            }

            result.push_back(curr);
        }

        return result;
    }
};

0199-binary-tree-right-side-view:
/*
    Given root of binary tree, return values that can only be seen from the right side

    BFS traversal, push right first before left, store only first value

    Time: O(n)
    Space: O(n)
*/

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    vector<int> rightSideView(TreeNode* root) {
        if (root == NULL) {
            return {};
        }

        queue<TreeNode*> q;
        q.push(root);

        vector<int> result;

        while (!q.empty()) {
            int count = q.size();

            for (int i = count; i > 0; i--) {
                TreeNode* node = q.front();
                q.pop();

                if (i == count) {
                    result.push_back(node->val);
                }

                if (node->right != NULL) {
                    q.push(node->right);
                }
                if (node->left != NULL) {
                    q.push(node->left);
                }
            }
        }

        return result;
    }
};

0101-symmetric-tree:
/*
    Given the root of a binary tree, this function checks whether the tree is symmetric,
    i.e., whether it is a mirror of itself around its center.

    Time Complexity: O(n), where n is the number of nodes in the binary tree.
    Space Complexity: O(n), due to the recursive stack space.

    Approach:
    - If the root is NULL, return true (base case).
    - Recursively check if the left subtree of the root is mirrored with the right subtree.
    - To check if two subtrees are mirrored, compare their left and right children recursively.

    Example:
    Input: root = [1,2,2,3,4,4,3]
    Output: true

    Input: root = [1,2,2,null,3,null,3]
    Output: false
*/

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    bool isSymmetric(TreeNode* root) {
        return dfs(root, root);
    }

    bool dfs(TreeNode* left, TreeNode* right) {
        if (!left && !right)
            return true;
        if (!left || !right)
            return false;

        return left->val == right->val && dfs(left->left, right->right) && dfs(left->right, right->left);
    }
};

0103-binary-tree-zigzag-level-order-trav:
/*
  Given the root of a binary tree, return the zigzag level order traversal of its nodes' values. 
  (i.e., from left to right, then right to left for the next level and alternate between).

  Ex. Input: root = [3,9,20,null,null,15,7]
      Output: [[3],[20,9],[15,7]]

