// Solution that can pass current tests
class Solution {
public:
    int findKthLargest(vector<int>& nums, int k) {
        int pivot = nums[rand() % nums.size()];
        vector<int> left, mid, right;
        for (auto num: nums) {
            if (num > pivot) left.push_back(num);
            else if (num == pivot) mid.push_back(num);
            else right.push_back(num);
        }
        if (k <= left.size()) return findKthLargest(left, k);
        else if (k <= left.size() + mid.size()) return mid[0];
        else return findKthLargest(right, k - left.size() - mid.size());
    }
};

0621-task-scheduler:
/*
    Given array of tasks & cooldown b/w same tasks, return least # of units of time
    Ex. tasks = ["A","A","A","B","B","B"] n = 2 -> 8 (A->B->idle->A->B->idle->A->B)

    Key is to determine # of idles, greedy: always arrange task w/ most freq first
    3A, 2B, 1C -> A??A??A -> AB?AB?A -> ABCAB#A, since A most freq, needs most idles

    Time: O(n)
    Space: O(1)
