0767-reorganize-string:
// Time: O(NlogN)
// Space: O(N)

class Solution {
public:
    string reorganizeString(string s) {
        string res="";

        unordered_map<char, int> mp;
        priority_queue<pair<int, char>> maxh;

        for(auto ch : s)
            mp[ch] += 1;

        for(auto m : mp)
            maxh.push(make_pair(m.second, m.first));

        while(maxh.size() > 1){
            auto top1= maxh.top();
            maxh.pop();
            auto top2 = maxh.top();
            maxh.pop();

            res += top1.second;
            res += top2.second;

            if(--top1.first > 0)
                maxh.push(top1);

            if(--top2.first > 0)
                maxh.push(top2);
        }

        if(!maxh.empty()){
            if(maxh.top().first > 1)
                return "";

            else
                res += maxh.top().second;
        }

        return res;
    }
};

1094-car-pooling:
class Solution {
public:
    bool carPooling(vector<vector<int>>& trips, int capacity) {
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> minHeap;
        for (int i=0; i<trips.size(); ++i) {
            int numPassengers=trips[i][0], from=trips[i][1], to=trips[i][2];
            minHeap.push({from, numPassengers});
            minHeap.push({to, -numPassengers});
        }

        int currCapacity = 0;
        while (!minHeap.empty()) {
            int currTime = minHeap.top().first;
            while (!minHeap.empty() and minHeap.top().first == currTime) {
                auto [time, numPassengers] = minHeap.top();
                minHeap.pop();
                currCapacity += numPassengers;
            }
            if (currCapacity > capacity)
                return false;
        }

        return true;
    }
};

0295-find-median-from-data-stream:
/*
    Implement data structure that gets the median from a data stream

    Max heap of lower values & min heap of higher values, access to mids

    Time: O(log n) + O(1)
    Space: O(n)
*/

class MedianFinder {
public:
    MedianFinder() {

    }

    void addNum(int num) {
        if (lower.empty()) {
            lower.push(num);
            return;
        }

        if (lower.size() > higher.size()) {
            if (lower.top() > num) {
                higher.push(lower.top());
                lower.pop();
                lower.push(num);
            } else {
                higher.push(num);
            }
        } else {
            if (num > higher.top()) {
                lower.push(higher.top());
                higher.pop();
                higher.push(num);
            } else {
                lower.push(num);
            }
        }
    }

    double findMedian() {
        double result = 0.0;

        if (lower.size() == higher.size()) {
            result = lower.top() + (higher.top() - lower.top()) / 2.0;
        } else {
            if (lower.size() > higher.size()) {
                result = lower.top();
            } else {
                result = higher.top();
            }
        }

        return result;
    }
private:
    priority_queue<int> lower;
    priority_queue<int, vector<int>, greater<int>> higher;
};

