Return the minimum number of dollars you need to travel every day in the given list of days.


Example. For days = [1,4,6,7,8,20] and costs = [2,7,15] we can buy a 1-day pass
     for costs[0] = $2, which covers day 1. On day 3 we can buy a 7-day pass
     for costs[1] = $7, which covers days 3,4....9. On day 20 we can again buy a
     1-day pass for costs[0] = $2 that will cover the 20th day. So in total we spent
     2 + 7 + 2 = $11 which is the minimum dollars needed for travelling in this case.


Time: O(n)
Space: O(n)

*/


class Solution {
public:
    int mincostTickets(vector<int>& days, vector<int>& costs) {

    vector<int> dp(days.size() + 1, 1e9);
    dp[days.size()] = 0;
    for(int i=days.size()-1; i>=0; i--) {
        for(int j=0; j<3; j++) {
            if(j == 0) {
                auto it = lower_bound(days.begin()+i, days.end(), days[i]+1);
                dp[i] = min(dp[i], costs[j] + dp[it-days.begin()]);
            }
            else if(j == 1) {
                auto it = lower_bound(days.begin()+i, days.end(), days[i]+7);
                dp[i] = min(dp[i], costs[j] + dp[it-days.begin()]);
            } else {
                auto it = lower_bound(days.begin()+i, days.end(), days[i]+30);
                dp[i] = min(dp[i], costs[j] + dp[it-days.begin()]);
            }
        }
    }
    return dp[0];

    }
};

0343-integer-break:
/*
Given an integer n, break it into the sum of k positive integers, where k >= 2, and maximize the product of those integers.
Return the maximum product that we can get.

Example. For n = 10, we can break it as 10 = 3 + 3 + 4. Product of these integers is 3 x 3 x 4 = 36, which is the maximum product that
     we can get in this case. So we return 36 as the answer. 


Time: O(n^2)
Space: O(n)

*/

class Solution {
public:
    int integerBreak(int n) {
        vector<int> dp(n+1, INT_MIN);
        dp[0] = 1, dp[1] = 1;
        for(int ind=2; ind<=n; ind++) {
            for(int i=ind-1; i>=1; i--) {
                dp[ind] = max(dp[ind], i * dp[ind - i]);
            }
            if(ind < n) dp[ind] = max(dp[ind], ind);
        }
        return dp[n];
    }
};

1137-n-th-tribonacci-number:
// Time: O(n)
// Space: O(1)

class Solution {
public:
    int tribonacci(int n) {
        int t[] = {0, 1, 1};
        if (n < 3) {
            return t[n];
        }
        for (int i = 3; i <= n; i++) {
            int sum_t = t[0] + t[1] + t[2];
            t[0] = t[1];
            t[1] = t[2];
            t[2] = sum_t;
        }
        return t[2];
    }
};

2140-solving-questions-with-brainpower:
// Time Complexity: O(n)
// Space Complexity: O(n)

class Solution
{
public:
    long long mostPoints(vector<vector<int>> &questions)
    {
        int n = questions.size();
        vector<long long> dp(n, 0);
        dp[n - 1] = questions[n - 1][0];
        long long ans = dp[n - 1];
        for (int i = n - 2; i >= 0; i--)
        {
            int k = i + questions[i][1] + 1;
            if (k < n)
            {
                dp[i] = (dp[k] + questions[i][0]) > dp[i + 1] ? (dp[k] + questions[i][0]) : dp[i + 1];
            }
            else
            {
                dp[i] = questions[i][0] > dp[i + 1] ? questions[i][0] : dp[i + 1];
            }
            ans = ans > dp[i] ? ans : dp[i];
        }
        return ans;
    }
};

0062-unique-paths:
/*
    Given grid, return # of unique paths from top-left to bottom-right
    Ex. m = 3, n = 2 -> 3 unique paths (R->D->D, D->D->R, D->R->D)

    DP: edges have 1 unique path, inner cells consider where it comes from
    Recurrence relation: grid[i][j] = grid[i-1][j] + grid[i][j-1]

    Time: O(m x n)
    Space: O(m x n)
*/

class Solution {
public:
    int uniquePaths(int m, int n) {
        vector<vector<int>> grid(m, vector<int>(n, 0));

        for (int i = 0; i < m; i++) {
            grid[i][0] = 1;
        }
        for (int j = 0; j < n; j++) {
            grid[0][j] = 1;
        }
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                grid[i][j] = grid[i - 1][j] + grid[i][j - 1];
            }
        }

        return grid[m - 1][n - 1];
    }
};

0063-unique-paths-ii:
/*

Given an m x n integer array grid. There is a robot initially located at the top-left corner (i.e., grid[0][0]). The robot tries to move to the bottom-right corner (i.e., grid[m - 1][n - 1]).
The robot can only move either down or right at any point in time. An obstacle and space are marked as 1 or 0 respectively in grid. A path that the robot takes cannot include any square that is an obstacle.

Return the number of possible unique paths that the robot can take to reach the bottom-right corner.

Example. obstacleGrid = [[0,0,0],[0,1,0],[0,0,0]]
     There is one obstacle in the middle of the 3x3 grid above.
     There are two ways to reach the bottom-right corner:
         1. Right -> Right -> Down -> Down
         2. Down -> Down -> Right -> Right
     So, the number of unique paths the robot can take is 2. Hence we return 2 as our answer.


Time: O(m * n)
Space: O(n)

*/


class Solution {
public:
    int uniquePathsWithObstacles(vector<vector<int>>& grid) {

        int m = grid.size(), n = grid[0].size();
        if(grid[m-1][n-1] == 1 || grid[0][0] == 1) return 0;
        vector<long long> dp(n);
        dp[n-1] = 1;
        for(int i=m-1; i>=0; i--) {
            for(int j=n-1; j>=0; j--) {
                if(grid[i][j] == 1) dp[j] = 0;
                else if(j == n-1) continue;
                else dp[j] = dp[j] + dp[j+1];
            }
        }
        return dp[0];

    }
};

1143-longest-common-subsequence:
/*
    Given 2 strings, return length of longest common subsequence
    Ex. text1 = "abcde", text2 = "ace" -> 3, "ace" is LCS

                j
            a   c   e
        a   3
        b       2     --> visualization of below, build DP bottom-up
    i   c       2
        d           1
        e           1

    Time: O(m x n)
    Space: O(m x n)
*/

class Solution {
public:
    int longestCommonSubsequence(string text1, string text2) {
        int m = text1.size();
        int n = text2.size();

        vector<vector<int>> dp(m + 1, vector<int>(n + 1));

        for (int i = m - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (text1[i] == text2[j]) {
                    dp[i][j] = 1 + dp[i + 1][j + 1];
                } else {
                    dp[i][j] = max(dp[i + 1][j], dp[i][j + 1]);
                }
            }
        }

        return dp[0][0];
    }
};

