class Solution {
public:
    bool isUgly(int n) {
        if(n <= 0)
            return false;

        for(int p: {2, 3, 5})
            while(n % p == 0)
                n = n / p;
        return n == 1;
    }
};

1260-shift-2d-grid:
class Solution {
public:
    vector<vector<int>> shiftGrid(vector<vector<int>>& grid, int k) {
        const int M = grid.size(), N = grid[0].size();

        auto posToVal = [&] (int r, int c) -> int {
            return r * N + c;};
        auto valToPos = [&] (int v) -> int* {
            return new int[] {v / N, v % N};};

        vector<vector<int>> res;
        for(int r = 0; r < M; r++) {
            vector<int> row;
            for(int c = 0; c < N; c++)
                row.push_back(0);
            res.push_back(row);
        }
        for(int r = 0; r < M; r++)
            for(int c = 0; c < N; c++) {
                int newVal = (posToVal(r, c) + k) % (M * N);
                int *newRC = valToPos(newVal);
                res[newRC[0]][newRC[1]] = grid[r][c];
            }
        return res;
    }
};

0013-roman-to-integer:
/*Roman numerals are represented by seven different symbols: I, V, X, L, C, D and M.

Symbol       Value
I             1
V             5
X             10
L             50
C             100
D             500
M             1000
For example, 2 is written as II in Roman numeral, just two ones added together. 12 is written as XII, which is simply X + II. The number 27 is written as XXVII, which is XX + V + II.

Roman numerals are usually written largest to smallest from left to right. However, the numeral for four is not IIII. Instead, the number four is written as IV. Because the one is before the five we subtract it making four. The same principle applies to the number nine, which is written as IX. There are six instances where subtraction is used:

I can be placed before V (5) and X (10) to make 4 and 9. 
X can be placed before L (50) and C (100) to make 40 and 90. 
C can be placed before D (500) and M (1000) to make 400 and 900.
Given a roman numeral, convert it to an integer. 
Example 3:

Input: s = "MCMXCIV"
Output: 1994
Explanation: M = 1000, CM = 900, XC = 90 and IV = 4. */

int prec(char x){
    switch(x){
        case 'I':
            return 1;
        case 'V':
            return 2;
        case 'X':
            return 3;
        case 'L':
            return 4;
        case 'C':
            return 5;
        case 'D':
            return 6;
        case 'M':
            return 7;
        default:
            return -1;
    }
}

int val(char x){
    switch(x){
        case 'I':
            return 1;
        case 'V':
            return 5;
        case 'X':
            return 10;
        case 'L':
            return 50;
        case 'C':
            return 100;
        case 'D':
            return 500;
        case 'M':
            return 1000;
        default:
            return -1;
    }
}

class Solution {
public:

        int romanToInt(string s)
        {
           int ans = 0;

           for(int i=0; i<s.length(); i++){
               if(prec(s[i]) >= prec(s[i+1])){
                   ans += val(s[i]);
               }
               else if(prec(s[i]) < prec(s[i+1])){
                   ans = ans - val(s[i]) + val(s[i+1]);
                   i++;
               }
           }

           return ans;
        }

};

0012-integer-to-roman:
/* Roman numerals are represented by seven different symbols: I, V, X, L, C, D and M.

Symbol       Value
I             1
V             5
X             10
L             50
C             100
D             500
M             1000
For example, 2 is written as II in Roman numeral, just two one's added together. 12 is written as XII, which is simply X + II. The number 27 is written as XXVII, which is XX + V + II.

Roman numerals are usually written largest to smallest from left to right. However, the numeral for four is not IIII. Instead, the number four is written as IV. Because the one is before the five we subtract it making four. The same principle applies to the number nine, which is written as IX. There are six instances where subtraction is used:

I can be placed before V (5) and X (10) to make 4 and 9. 
X can be placed before L (50) and C (100) to make 40 and 90. 
C can be placed before D (500) and M (1000) to make 400 and 900.
Given an integer, convert it to a roman numeral.
Example 
Input: num = 1994
Output: "MCMXCIV"
Explanation: M = 1000, CM = 900, XC = 90 and IV = 4. */

class Solution {
public:
    string intToRoman(int num) {
       string s="";
       while(num>=1000)
       {
           s+="M";
           num=num-1000;
       }
       if(num>=900)
       {
           s+="CM";
           num=num-900;
       }
       while(num>=500)
       {
           s+="D";
           num=num-500;
       }
       if(num>=400)
       {
           s+="CD";
           num=num-400;
       }
       while(num>=100)
       {
           s+="C";
           num=num-100;
       }
       if(num>=90)
       {
           s+="XC";
           num=num-90;
       }
       while(num>=50)
       {
           s+="L";
           num=num-50;
       }
       if(num>=40)
       {
           s+="XL";
           num=num-40;
       }
       while(num>=10)
       {
           s+="X";
           num=num-10;
       }
       if(num>=9)
       {
           s+="IX";
           num=num-9;
       }
       while(num>=5)
       {
           s+="V";
           num=num-5;
       }
       if(num>=4)
       {
           s+="IV";
           num=num-4;
       }
       while(num>=1)
       {
           s+="I";
           num=num-1;
       }
       return s; 
    }
};

