    vector<int> shuffle(vector<int>& nums, int n) {
        int lp = 0;
        int rp = n;
        int p = 0;
        vector<int> shuffled(2*n);

        while (p < 2 * n) {
            shuffled[p++] = nums[lp++];
            shuffled[p++] = nums[rp++];
        }
        return shuffled;
    }
};

0371-sum-of-two-integers:
/*
    Given 2 ints, return sum w/o using +/-
    Ex. a = 1 b = 2 -> 3, a = 2 b = 3 -> 5

    XOR for addition, AND for carry bit

    Time: O(n)
    Space: O(1)
*/

class Solution {
public:
    int getSum(int a, int b) {
        while (b != 0) {
            int carry = a & b;
            a = a ^ b;
            b = (unsigned)carry << 1;
        }
        return a;
    }
};

0007-reverse-integer:
/*
    Given a signed 32-bit integer, return it with its digits reversed
    Ex. x = 123 -> 321, x = -123 -> -321, x = 120 -> 21

    Reverse bit-by-bit starting from right, shift right off every time

    Time: O(log x)
    Space: O(1)
*/

class Solution {
public:
    int reverse(int x) {
        int rev = 0;
        while (x != 0) {
            int temp = x % 10;
            x /= 10;
            if (rev > INT_MAX / 10 || (rev == INT_MAX / 10 && temp > 7)) {
                return 0;
            }
            if (rev < INT_MIN / 10 || (rev == INT_MIN / 10 && temp < -8)) {
                return 0;
            }
            rev = rev * 10 + temp;
        }
        return rev;
    }
};

0067-add-binary:
class Solution {
public:
    string addBinary(string a, string b) {
        string res;
        int maxLen = a.size() > b.size() ? a.size() : b.size();
        unsigned int carry = 0;

        for(int i = 0; i < maxLen; i++)
        {
            unsigned int bitA = i < a.size() ? a[a.size() - i - 1] - '0' : 0;
            unsigned int bitB = i < b.size() ? b[b.size() - i - 1] - '0' : 0;

            unsigned int total = bitA + bitB + carry;
            char sum = '0' + total % 2;
            carry = total / 2;

            // Add to the beginning of the string
            res.insert(0, 1, sum);
        }

        if(carry)
        {
            res.insert(0, 1, '1');
        }

        return res;
    }
};
